template.query:
mutation ArchiveCompletedTodos($olderThanDays: Int = 30) {
  archiveNodes(
    tableId: "58"
    criteria: {
      attributeFilter: { name: "status", value: "DONE" }
      olderThanDays: $olderThanDays
    }
    options: {
      createBackup: true
      deleteOriginal: false
      archiveFormat: "JSON"
    }
  ) {
    success
    archivedCount
    backupLocation
    errors {
      message
    }
    summary {
      totalCompleted
      archivedTodos
      oldestTodoDate
      newestTodoDate
    }
  }
}
